{"key":"current_owl","value":"@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#INVOIC-Ontology> a owl:Ontology ;
    rdfs:label "EDIFACT D96A INVOIC Ontology" ;
    rdfs:comment "A comprehensive OWL2 ontology for UN/EDIFACT D96A INVOIC messages, covering all mandatory segments, roles, and validation constraints for semantic interoperability and compliance with EN 16931-1." .

###################################################################
# CLASSES
###################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The outermost envelope containing one or more EDIFACT messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A business message within the interchange envelope, e.g., INVOIC." .

:InvoiceMessage a owl:Class ;
    rdfs:label "Invoice Message (INVOIC)" ;
    rdfs:comment "The INVOIC message for global trade, subclass of Message." ;
    rdfs:subClassOf :Message .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment in an EDIFACT message, e.g., BGM, NAD, DTM, etc." .

# Segment subclasses
:UNH_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "UNH Segment" ; rdfs:comment "Message header segment (UNH) for INVOIC." .
:UNT_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "UNT Segment" ; rdfs:comment "Message trailer segment (UNT) for INVOIC." .
:BGM_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "BGM Segment" ; rdfs:comment "Beginning of message segment (BGM)." .
:NAD_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "NAD Segment" ; rdfs:comment "Name and address segment (NAD) for parties and roles." .
:DTM_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "DTM Segment" ; rdfs:comment "Date/time/period segment (DTM), e.g., invoice date, delivery date." .
:MOA_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "MOA Segment" ; rdfs:comment "Monetary amount segment (MOA), e.g., invoice total, line totals." .
:QTY_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "QTY Segment" ; rdfs:comment "Quantity segment (QTY), e.g., item quantity." .
:PRI_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "PRI Segment" ; rdfs:comment "Price segment (PRI), e.g., net price per item." .
:TAX_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "TAX Segment" ; rdfs:comment "Tax segment (TAX), e.g., VAT details." .
:RFF_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "RFF Segment" ; rdfs:comment "Reference segment (RFF), e.g., invoice number, order reference." .
:ALC_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "ALC Segment" ; rdfs:comment "Allowance/charge segment (ALC) for discounts, surcharges." .
:LIN_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "LIN Segment" ; rdfs:comment "Line item identifier segment (LIN)." .
:IMD_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "IMD Segment" ; rdfs:comment "Item description segment (IMD)." .
:PIA_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "PIA Segment" ; rdfs:comment "Additional product ID segment (PIA)." .
:PAC_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "PAC Segment" ; rdfs:comment "Packaging segment (PAC)." .
:CUX_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "CUX Segment" ; rdfs:comment "Currency segment (CUX) for currency details." .
:TOD_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "TOD Segment" ; rdfs:comment "Terms of delivery segment (TOD)." .
:LOC_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "LOC Segment" ; rdfs:comment "Location segment (LOC) for logistics." .
:FTX_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "FTX Segment" ; rdfs:comment "Free text segment (FTX) for invoice notes and legal text." .
:PAT_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "PAT Segment" ; rdfs:comment "Payment terms segment (PAT) for due dates, terms, penalties." .
:PCD_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "PCD Segment" ; rdfs:comment "Percentage details segment (PCD) for discounts, surcharges." .
:TDT_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "TDT Segment" ; rdfs:comment "Transport details segment (TDT) for shipping/transport." .
:MEA_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "MEA Segment" ; rdfs:comment "Measurement segment (MEA) for weights, dimensions." .

# Data structure classes
:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite or segment." .

# Pivot and core business classes
:InvoiceHeader a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Invoice Header" ;
    rdfs:comment "Header section of the invoice, containing document dates and references." .

:InvoiceDetail a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Invoice Detail" ;
    rdfs:comment "Detail section listing individual line items." .

:InvoiceSummary a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Invoice Summary" ;
    rdfs:comment "Summary section providing totals, taxes, and payment terms." .

:LineItem a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Line Item (pivot)" ;
    rdfs:comment "Pivot class for line-level reification (item, price, quantity, etc.)." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A business entity involved in the invoice (buyer, supplier, etc.)." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role that an organization plays in the invoice (buyer, delivery party, etc.)." .

:RoleAssignment a owl:Class ;
    rdfs:label "Role Assignment (pivot)" ;
    rdfs:comment "Pivot class for reifying the assignment of a role to an organization within a message context." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal or physical address associated with an organization." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service listed in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A monetary price, e.g., for an item or invoice total." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "A tax entity, e.g., VAT." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "An identifier such as Global Location Number (GLN)." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice is assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A SHACL or OWL-based validation constraint for the invoice." .

###################################################################
# OBJECT PROPERTIES
###################################################################

:containsMessage a owl:ObjectProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an Interchange Envelope to its contained Message(s)." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    owl:FunctionalProperty .

:hasSegment a owl:ObjectProperty ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a Message to its Segments." ;
    rdfs:domain :Message ;
    rdfs:range :Segment .

:hasCompositeElement a owl:ObjectProperty ;
    rdfs:label "has composite element" ;
    rdfs:comment "Links a Segment to its Composite Data Elements." ;
    rdfs:domain :Segment ;
    rdfs:range :CompositeDataElement .

:hasSimpleElement a owl:ObjectProperty ;
    rdfs:label "has simple element" ;
    rdfs:comment "Links a Composite Data Element to its Simple Data Elements." ;
    rdfs:domain :CompositeDataElement ;
    rdfs:range :SimpleDataElement .

:hasHeader a owl:ObjectProperty ;
    rdfs:label "has header" ;
    rdfs:comment "Links an Invoice Message to its header section." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceHeader ;
    owl:FunctionalProperty .

:hasDetail a owl:ObjectProperty ;
    rdfs:label "has detail" ;
    rdfs:comment "Links an Invoice Message to its detail section." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceDetail ;
    owl:FunctionalProperty .

:hasSummary a owl:ObjectProperty ;
    rdfs:label "has summary" ;
    rdfs:comment "Links an Invoice Message to its summary section." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceSummary ;
    owl:FunctionalProperty .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:label "involves organization" ;
    rdfs:comment "Links an Invoice Message to involved Organizations." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization .

:hasAgentRole a owl:ObjectProperty ;
    rdfs:label "has agent role" ;
    rdfs:comment "Links an Organization to its Agent Roles." ;
    rdfs:domain :Organization ;
    rdfs:range :AgentRole .

:assignedRole a owl:ObjectProperty ;
    rdfs:label "assigned role" ;
    rdfs:comment "Links a RoleAssignment to its AgentRole." ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :AgentRole ;
    owl:FunctionalProperty .

:assignedToOrganization a owl:ObjectProperty ;
    rdfs:label "assigned to organization" ;
    rdfs:comment "Links a RoleAssignment to the Organization playing the role." ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :Organization ;
    owl:FunctionalProperty .

:assignedInContext a owl:ObjectProperty ;
    rdfs:label "assigned in context" ;
    rdfs:comment "Links a RoleAssignment to the Invoice Message context." ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :InvoiceMessage ;
    owl:FunctionalProperty .

:hasAddress a owl:ObjectProperty ;
    rdfs:label "has address" ;
    rdfs:comment "Links an Organization to its Address." ;
    rdfs:domain :Organization ;
    rdfs:range :Address .

:hasIdentifier a owl:ObjectProperty ;
    rdfs:label "has identifier" ;
    rdfs:comment "Links an Organization to its Identifier (e.g., GLN)." ;
    rdfs:domain :Organization ;
    rdfs:range :Identifier ;
    owl:FunctionalProperty .

:hasLineItem a owl:ObjectProperty ;
    rdfs:label "has line item" ;
    rdfs:comment "Links an InvoiceDetail to its LineItems." ;
    rdfs:domain :InvoiceDetail ;
    rdfs:range :LineItem .

:describesItem a owl:ObjectProperty ;
    rdfs:label "describes item" ;
    rdfs:comment "Links a LineItem to the Item it describes." ;
    rdfs:domain :LineItem ;
    rdfs:range :Item ;
    owl:FunctionalProperty .

:hasQuantity a owl:ObjectProperty ;
    rdfs:label "has quantity" ;
    rdfs:comment "Links a LineItem to its QTY_Segment." ;
    rdfs:domain :LineItem ;
    rdfs:range :QTY_Segment .

:hasNetPrice a owl:ObjectProperty ;
    rdfs:label "has net price" ;
    rdfs:comment "Links a LineItem to its PRI_Segment (net price)." ;
    rdfs:domain :LineItem ;
    rdfs:range :PRI_Segment ;
    owl:FunctionalProperty .

:hasTotalTax a owl:ObjectProperty ;
    rdfs:label "has total tax" ;
    rdfs:comment "Links an InvoiceSummary to its TAX_Segment (total tax)." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :TAX_Segment ;
    owl:FunctionalProperty .

:hasTotalAmount a owl:ObjectProperty ;
    rdfs:label "has total amount" ;
    rdfs:comment "Links an InvoiceSummary to its MOA_Segment (total amount)." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :MOA_Segment ;
    owl:FunctionalProperty .

:hasInvoiceNumber a owl:ObjectProperty ;
    rdfs:label "has invoice number" ;
    rdfs:comment "Links an InvoiceHeader to its RFF_Segment (invoice number)." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :RFF_Segment ;
    owl:FunctionalProperty .

:hasDocumentDate a owl:ObjectProperty ;
    rdfs:label "has document date" ;
    rdfs:comment "Links an InvoiceHeader to its DTM_Segment (document date)." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :DTM_Segment ;
    owl:FunctionalProperty .

:hasReferenceNumber a owl:ObjectProperty ;
    rdfs:label "has reference number" ;
    rdfs:comment "Links an InvoiceHeader to its RFF_Segment (reference number)." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :RFF_Segment ;
    owl:FunctionalProperty .

:isAssignedToBusinessProcess a owl:ObjectProperty ;
    rdfs:label "is assigned to business process" ;
    rdfs:comment "Links an InvoiceMessage to a BusinessProcess." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess .

:hasValidationConstraint a owl:ObjectProperty ;
    rdfs:label "has validation constraint" ;
    rdfs:comment "Links an InvoiceMessage to a ValidationConstraint (e.g., for SHACL/OWL validation)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ValidationConstraint .

:hasMandatoryIdentifier a owl:ObjectProperty ;
    rdfs:label "has mandatory identifier" ;
    rdfs:comment "Links an InvoiceMessage to mandatory Identifiers (e.g., GLN)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Identifier .

:hasAllowanceOrCharge a owl:ObjectProperty ;
    rdfs:label "has allowance or charge" ;
    rdfs:comment "Links an InvoiceSummary to its ALC_Segment (allowances/charges)." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :ALC_Segment .

:hasTax a owl:ObjectProperty ;
    rdfs:label "has tax" ;
    rdfs:comment "Links an InvoiceSummary to its TAX_Segment(s)." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :TAX_Segment .

:hasReference a owl:ObjectProperty ;
    rdfs:label "has reference" ;
    rdfs:comment "Links an InvoiceHeader to its RFF_Segment (other references)." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :RFF_Segment .

:hasMessageHeader a owl:ObjectProperty ;
    rdfs:label "has message header" ;
    rdfs:comment "Links an InvoiceMessage to its UNH_Segment (message header)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :UNH_Segment ;
    owl:FunctionalProperty .

:hasMessageTrailer a owl:ObjectProperty ;
    rdfs:label "has message trailer" ;
    rdfs:comment "Links an InvoiceMessage to its UNT_Segment (message trailer)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :UNT_Segment ;
    owl:FunctionalProperty .

:hasLineIdentifier a owl:ObjectProperty ;
    rdfs:label "has line identifier" ;
    rdfs:comment "Links a LineItem to its LIN_Segment (line identifier)." ;
    rdfs:domain :LineItem ;
    rdfs:range :LIN_Segment ;
    owl:FunctionalProperty .

:hasItemDescription a owl:ObjectProperty ;
    rdfs:label "has item description" ;
    rdfs:comment "Links a LineItem to its IMD_Segment (item description)." ;
    rdfs:domain :LineItem ;
    rdfs:range :IMD_Segment .

:hasAdditionalProductID a owl:ObjectProperty ;
    rdfs:label "has additional product ID" ;
    rdfs:comment "Links a LineItem to its PIA_Segment (additional product IDs)." ;
    rdfs:domain :LineItem ;
    rdfs:range :PIA_Segment .

:hasPackaging a owl:ObjectProperty ;
    rdfs:label "has packaging" ;
    rdfs:comment "Links a LineItem to its PAC_Segment (packaging)." ;
    rdfs:domain :LineItem ;
    rdfs:range :PAC_Segment .

:hasCurrency a owl:ObjectProperty ;
    rdfs:label "has currency" ;
    rdfs:comment "Links an InvoiceSummary to its CUX_Segment (currency details)." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :CUX_Segment ;
    owl:FunctionalProperty .

:hasTermsOfDelivery a owl:ObjectProperty ;
    rdfs:label "has terms of delivery" ;
    rdfs:comment "Links an InvoiceSummary to its TOD_Segment (terms of delivery)." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :TOD_Segment ;
    owl:FunctionalProperty .

:hasLocation a owl:ObjectProperty ;
    rdfs:label "has location" ;
    rdfs:comment "Links an InvoiceSummary to its LOC_Segment (location/logistics)." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :LOC_Segment .

:hasFreeText a owl:ObjectProperty ;
    rdfs:label "has free text" ;
    rdfs:comment "Links an InvoiceMessage to its FTX_Segment(s) (free text/legal notes)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :FTX_Segment .

:hasFreeTextLine a owl:ObjectProperty ;
    rdfs:label "has free text line" ;
    rdfs:comment "Links a LineItem to its FTX_Segment(s)." ;
    rdfs:domain :LineItem ;
    rdfs:range :FTX_Segment .

:hasReferenceLine a owl:ObjectProperty ;
    rdfs:label "has reference line" ;
    rdfs:comment "Links a LineItem to its RFF_Segment(s) (line-level references)." ;
    rdfs:domain :LineItem ;
    rdfs:range :RFF_Segment .

:hasDateLine a owl:ObjectProperty ;
    rdfs:label "has date line" ;
    rdfs:comment "Links a LineItem to its DTM_Segment(s) (line-level dates)." ;
    rdfs:domain :LineItem ;
    rdfs:range :DTM_Segment .

:hasAllowanceOrChargeLine a owl:ObjectProperty ;
    rdfs:label "has allowance or charge line" ;
    rdfs:comment "Links a LineItem to its ALC_Segment(s) (allowance/charge details)." ;
    rdfs:domain :LineItem ;
    rdfs:range :ALC_Segment .

:hasPaymentTerms a owl:ObjectProperty ;
    rdfs:label "has payment terms" ;
    rdfs:comment "Links an InvoiceSummary to its PAT_Segment (payment terms)." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :PAT_Segment ;
    owl:FunctionalProperty .

:hasPercentageDetails a owl:ObjectProperty ;
    rdfs:label "has percentage details" ;
    rdfs:comment "Links an InvoiceSummary to its PCD_Segment(s)." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :PCD_Segment .

:hasTransportDetails a owl:ObjectProperty ;
    rdfs:label "has transport details" ;
    rdfs:comment "Links an InvoiceSummary to its TDT_Segment(s)." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :TDT_Segment .

:hasMeasurement a owl:ObjectProperty ;
    rdfs:label "has measurement" ;
    rdfs:comment "Links an InvoiceSummary to its MEA_Segment(s)." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :MEA_Segment .

:hasPaymentTermsLine a owl:ObjectProperty ;
    rdfs:label "has payment terms line" ;
    rdfs:comment "Links a LineItem to its PAT_Segment(s) (payment terms)." ;
    rdfs:domain :LineItem ;
    rdfs:range :PAT_Segment .

:hasPercentageDetailsLine a owl:ObjectProperty ;
    rdfs:label "has percentage details line" ;
    rdfs:comment "Links a LineItem to its PCD_Segment(s)." ;
    rdfs:domain :LineItem ;
    rdfs:range :PCD_Segment .

:hasTransportDetailsLine a owl:ObjectProperty ;
    rdfs:label "has transport details line" ;
    rdfs:comment "Links a LineItem to its TDT_Segment(s)." ;
    rdfs:domain :LineItem ;
    rdfs:range :TDT_Segment .

:hasMeasurementLine a owl:ObjectProperty ;
    rdfs:label "has measurement line" ;
    rdfs:comment "Links a LineItem to its MEA_Segment(s)." ;
    rdfs:domain :LineItem ;
    rdfs:range :MEA_Segment .

###################################################################
# DATA PROPERTIES
###################################################################

:hasGLN a owl:DatatypeProperty ;
    rdfs:label "has GLN" ;
    rdfs:comment "Links an Identifier to its Global Location Number (GLN) as a string." ;
    rdfs:domain :Identifier ;
    rdfs:range xsd:string ;
    owl:FunctionalProperty .

###################################################################
# COMPLEX AXIOMS & RESTRICTIONS
###################################################################

# Example: InvoiceSummary must have at least one total amount (MOA_Segment)
:InvoiceSummary rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :hasTotalAmount ;
    owl:someValuesFrom :MOA_Segment
] .

# Example: LineItem must have at least one quantity (QTY_Segment)
:LineItem rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :hasQuantity ;
    owl:someValuesFrom :QTY_Segment
] .

# Example: LineItem must have at least one net price (PRI_Segment)
:LineItem rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :hasNetPrice ;
    owl:someValuesFrom :PRI_Segment
] .

# Example: InvoiceMessage must have a message header (UNH_Segment)
:InvoiceMessage rdfs:subClassOf [
    a owl:Restriction ;
    owl:onProperty :hasMessageHeader ;
    owl:someValuesFrom :UNH_Segment
] .

# Example: ValidationConstraint for arithmetic consistency
:ValidationConstraint rdfs:comment "Constraint: The sum of all LineItem net amounts (MOA_Segment) must equal the InvoiceSummary total amount (MOA_Segment)." .

###################################################################
# DISJOINTNESS
###################################################################

:Organization owl:disjointWith :Address .
:Message owl:disjointWith :Segment .
:CompositeDataElement owl:disjointWith :SimpleDataElement .

###################################################################
# ANNOTATIONS (for all classes/properties above)
###################################################################
# (Already included inline for each class/property)
"}

