@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#INVOIC-Ontology> a owl:Ontology ;
    rdfs:label "EDIFACT D96A INVOIC Ontology" ;
    rdfs:comment "A comprehensive OWL2 ontology for UN/EDIFACT D96A INVOIC messages, covering all mandatory segments, roles, and validation constraints for semantic interoperability and compliance with EN 16931-1." .

###################################################################
# CLASSES
###################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The outermost envelope containing one or more EDIFACT messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A business message within the interchange envelope, e.g., INVOIC." .

:InvoiceMessage a owl:Class ;
    rdfs:label "Invoice Message (INVOIC)" ;
    rdfs:comment "The INVOIC message for global trade, subclass of Message." ;
    rdfs:subClassOf :Message .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment in an EDIFACT message, e.g., BGM, NAD, DTM, etc." .

# Segment subclasses
:UNH_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "UNH Segment" ; rdfs:comment "Message header segment (UNH) for INVOIC." .
:UNT_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "UNT Segment" ; rdfs:comment "Message trailer segment (UNT) for INVOIC." .
:BGM_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "BGM Segment" ; rdfs:comment "Beginning of message segment (BGM)." .
:NAD_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "NAD Segment" ; rdfs:comment "Name and address segment (NAD) for parties and roles." .
:DTM_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "DTM Segment" ; rdfs:comment "Date/time/period segment (DTM), e.g., invoice date, delivery date." .
:MOA_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "MOA Segment" ; rdfs:comment "Monetary amount segment (MOA), e.g., invoice total, line totals." .
:QTY_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "QTY Segment" ; rdfs:comment "Quantity segment (QTY), e.g., item quantity." .
:PRI_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "PRI Segment" ; rdfs:comment "Price segment (PRI), e.g., net price per item." .
:TAX_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "TAX Segment" ; rdfs:comment "Tax segment (TAX), e.g., VAT details." .
:RFF_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "RFF Segment" ; rdfs:comment "Reference segment (RFF), e.g., invoice number, order reference." .
:ALC_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "ALC Segment" ; rdfs:comment "Allowance/charge segment (ALC) for discounts, surcharges." .
:LIN_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "LIN Segment" ; rdfs:comment "Line item identifier segment (LIN)." .
:IMD_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "IMD Segment" ; rdfs:comment "Item description segment (IMD)." .
:PIA_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "PIA Segment" ; rdfs:comment "Additional product ID segment (PIA)." .
:PAC_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "PAC Segment" ; rdfs:comment "Packaging segment (PAC)." .
