{"owl_content": "@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#INVOIC-Ontology> a owl:Ontology ;
    rdfs:label "EDIFACT D96A INVOIC Ontology" ;
    rdfs:comment "A comprehensive OWL2 ontology for UN/EDIFACT D96A INVOIC messages, covering all mandatory segments, roles, and validation constraints for semantic interoperability and compliance with EN 16931-1." .

###################################################################
# CLASSES
###################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The outermost envelope containing one or more EDIFACT messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A business message within the interchange envelope, e.g., INVOIC." .

:InvoiceMessage a owl:Class ;
    rdfs:label "Invoice Message (INVOIC)" ;
    rdfs:comment "The INVOIC message for global trade, subclass of Message." ;
    rdfs:subClassOf :Message .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment in an EDIFACT message, e.g., BGM, NAD, DTM, etc." .

# Segment subclasses
:UNH_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "UNH Segment" ; rdfs:comment "Message header segment (UNH) for INVOIC." .
:UNT_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "UNT Segment" ; rdfs:comment "Message trailer segment (UNT) for INVOIC." .
:BGM_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "BGM Segment" ; rdfs:comment "Beginning of message segment (BGM)." .
:NAD_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "NAD Segment" ; rdfs:comment "Name and address segment (NAD) for parties and roles." .
:DTM_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "DTM Segment" ; rdfs:comment "Date/time/period segment (DTM), e.g., invoice date, delivery date." .
:MOA_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "MOA Segment" ; rdfs:comment "Monetary amount segment (MOA), e.g., invoice total, line totals." .
:QTY_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "QTY Segment" ; rdfs:comment "Quantity segment (QTY), e.g., item quantity." .
:PRI_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "PRI Segment" ; rdfs:comment "Price segment (PRI), e.g., net price per item." .
:TAX_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "TAX Segment" ; rdfs:comment "Tax segment (TAX), e.g., VAT details." .
:RFF_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "RFF Segment" ; rdfs:comment "Reference segment (RFF), e.g., invoice number, order reference." .
:ALC_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "ALC Segment" ; rdfs:comment "Allowance/charge segment (ALC) for discounts, surcharges." .
:LIN_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "LIN Segment" ; rdfs:comment "Line item identifier segment (LIN)." .
:IMD_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "IMD Segment" ; rdfs:comment "Item description segment (IMD)." .
:PIA_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "PIA Segment" ; rdfs:comment "Additional product ID segment (PIA)." .
:PAC_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "PAC Segment" ; rdfs:comment "Packaging segment (PAC)." .
:CUX_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "CUX Segment" ; rdfs:comment "Currency segment (CUX) for currency details." .
:TOD_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "TOD Segment" ; rdfs:comment "Terms of delivery segment (TOD)." .
:LOC_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "LOC Segment" ; rdfs:comment "Location segment (LOC) for logistics." .
:FTX_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "FTX Segment" ; rdfs:comment "Free text segment (FTX) for invoice notes and legal text." .
:PAT_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "PAT Segment" ; rdfs:comment "Payment terms segment (PAT) for due dates, terms, penalties." .
:PCD_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "PCD Segment" ; rdfs:comment "Percentage details segment (PCD) for discounts, surcharges." .
:TDT_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "TDT Segment" ; rdfs:comment "Transport details segment (TDT) for shipping/transport." .
:MEA_Segment a owl:Class ; rdfs:subClassOf :Segment ; rdfs:label "MEA Segment" ; rdfs:comment "Measurement segment (MEA) for weights, dimensions." .

# Data structure classes
:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite or segment." .

# Pivot and core business classes
:InvoiceHeader a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Invoice Header" ;
    rdfs:comment "Header section of the invoice, containing document dates and references." .

:InvoiceDetail a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Invoice Detail" ;
    rdfs:comment "Detail section listing individual line items." .

:InvoiceSummary a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Invoice Summary" ;
    rdfs:comment "Summary section providing totals, taxes, and payment terms." .

:LineItem a owl:Class ;
    rdfs:subClassOf :CompositeDataElement ;
    rdfs:label "Line Item (pivot)" ;
    rdfs:comment "Pivot class for line-level reification (item, price, quantity, etc.)." .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A business entity involved in the invoice (buyer, supplier, etc.)." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role that an organization plays in the invoice (buyer, delivery party, etc.)." .

:RoleAssignment a owl:Class ;
    rdfs:label "Role Assignment (pivot)" ;
    rdfs:comment "Pivot class for reifying the assignment of a role to an organization within a message context." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal or physical address associated with an organization." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service listed in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A monetary price, e.g., for an item or invoice total." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "A tax entity, e.g., VAT." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "An identifier such as Global Location Number (GLN)." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice is assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A SHACL or OWL-based validation constraint for the invoice." .

###################################################################
# OBJECT PROPERTIES
###################################################################

:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an Interchange Envelope to its contained Message(s)." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message .

:hasSegment a owl:ObjectProperty ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a Message to its Segments." ;
    rdfs:domain :Message ;
    rdfs:range :Segment .

