    rdfs:comment "Pivot class for reifying the assignment of a role to an organization within a message context." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal or physical address associated with an organization." .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or service listed in the invoice." .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A monetary price, e.g., for an item or invoice total." .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "A tax entity, e.g., VAT." .

:Identifier a owl:Class ;
    rdfs:label "Identifier" ;
    rdfs:comment "An identifier such as Global Location Number (GLN)." .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process to which the invoice is assigned." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A SHACL or OWL-based validation constraint for the invoice." .

