#################################################################

[] a owl:AllDisjointClasses ;
    owl:members ( :InvoiceHeader :InvoiceDetail :InvoiceSummary ) .

[] a owl:AllDisjointClasses ;
    owl:members ( :Organization :AgentRole :Address :LineItem :Item :Price :Tax :ReferenceNumber :BusinessProcess ) .

