@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix : <http://www.example.org/ontology#> .

<http://www.example.org/ontology#storyid> a owl:Ontology ;
    rdfs:label "EDIFACT D96A Invoice Ontology" ;
    rdfs:comment "A profoundly structured OWL2 ontology for UN/EDIFACT D96A Invoice (INVOIC) messages, supporting EN 16931-1 and P2P-O alignment." .

#################################################################
# Classes
#################################################################

:InterchangeEnvelope a owl:Class ;
    rdfs:label "Interchange Envelope" ;
    rdfs:comment "The top-level envelope containing one or more EDIFACT messages." .

:Message a owl:Class ;
    rdfs:label "Message" ;
    rdfs:comment "A generic EDIFACT message." .

:InvoiceMessage a owl:Class ;
    rdfs:label "Invoice Message" ;
    rdfs:comment "An EDIFACT INVOIC message, a subclass of Message." ;
    rdfs:subClassOf :Message .

:Segment a owl:Class ;
    rdfs:label "Segment" ;
    rdfs:comment "A segment within an EDIFACT message." .

:BGM_Segment a owl:Class ;
    rdfs:label "BGM Segment" ;
    rdfs:comment "Beginning of Message segment for document identification." ;
    rdfs:subClassOf :Segment .

:NADSegment a owl:Class ;
    rdfs:label "NAD Segment" ;
    rdfs:comment "Name and Address segment for participant details." ;
    rdfs:subClassOf :Segment .

:DTMSegment a owl:Class ;
    rdfs:label "DTM Segment" ;
    rdfs:comment "Date/Time/Period segment. Contains qualifier and value." ;
    rdfs:subClassOf :Segment .

:MOASegment a owl:Class ;
    rdfs:label "MOA Segment" ;
    rdfs:comment "Monetary Amount segment. Contains qualifier and amount value." ;
    rdfs:subClassOf :Segment .

:RFFSegment a owl:Class ;
    rdfs:label "RFF Segment" ;
    rdfs:comment "Reference segment for reference numbers." ;
    rdfs:subClassOf :Segment .

:LOCSegment a owl:Class ;
    rdfs:label "LOC Segment" ;
    rdfs:comment "Location segment for delivery or other locations." ;
    rdfs:subClassOf :Segment .

:LINSegment a owl:Class ;
    rdfs:label "LIN Segment" ;
    rdfs:comment "Line Item segment." ;
    rdfs:subClassOf :Segment .

:PRISegment a owl:Class ;
    rdfs:label "PRI Segment" ;
    rdfs:comment "Price segment." ;
    rdfs:subClassOf :Segment .

:QTYSegment a owl:Class ;
    rdfs:label "QTY Segment" ;
    rdfs:comment "Quantity segment." ;
    rdfs:subClassOf :Segment .

:TAXSegment a owl:Class ;
    rdfs:label "TAX Segment" ;
    rdfs:comment "Tax segment." ;
    rdfs:subClassOf :Segment .

:CUXSegment a owl:Class ;
    rdfs:label "CUX Segment" ;
    rdfs:comment "Currency segment." ;
    rdfs:subClassOf :Segment .

:UNSSegment a owl:Class ;
    rdfs:label "UNS Segment" ;
    rdfs:comment "Section control segment (header/detail/summary separator)." ;
    rdfs:subClassOf :Segment .

:CompositeDataElement a owl:Class ;
    rdfs:label "Composite Data Element" ;
    rdfs:comment "A composite data element within a segment." .

:SimpleDataElement a owl:Class ;
    rdfs:label "Simple Data Element" ;
    rdfs:comment "A simple data element within a composite or segment." .

:InvoiceHeader a owl:Class ;
    rdfs:label "Invoice Header" ;
    rdfs:comment "Header section of an invoice message." ;
    rdfs:subClassOf :CompositeDataElement .

:InvoiceDetail a owl:Class ;
    rdfs:label "Invoice Detail" ;
    rdfs:comment "Detail section of an invoice message." ;
    rdfs:subClassOf :CompositeDataElement .

:InvoiceSummary a owl:Class ;
    rdfs:label "Invoice Summary" ;
    rdfs:comment "Summary section of an invoice message." ;
    rdfs:subClassOf :CompositeDataElement .

:Organization a owl:Class ;
    rdfs:label "Organization" ;
    rdfs:comment "A legal entity involved in the transaction." .

:AgentRole a owl:Class ;
    rdfs:label "Agent Role" ;
    rdfs:comment "A role played by an organization (e.g., Buyer, Supplier, Delivery Party)." .

:Address a owl:Class ;
    rdfs:label "Address" ;
    rdfs:comment "A postal or physical address." ;
    rdfs:subClassOf :CompositeDataElement .

:LineItem a owl:Class ;
    rdfs:label "Line Item" ;
    rdfs:comment "An itemized entry in the invoice detail section." ;
    rdfs:subClassOf :CompositeDataElement .

:Item a owl:Class ;
    rdfs:label "Item" ;
    rdfs:comment "A product or good referenced in the invoice." ;
    rdfs:subClassOf :CompositeDataElement .

:Price a owl:Class ;
    rdfs:label "Price" ;
    rdfs:comment "A price associated with an item or invoice." ;
    rdfs:subClassOf :CompositeDataElement .

:Tax a owl:Class ;
    rdfs:label "Tax" ;
    rdfs:comment "A tax applied to the invoice or line item." ;
    rdfs:subClassOf :CompositeDataElement .

:ReferenceNumber a owl:Class ;
    rdfs:label "Reference Number" ;
    rdfs:comment "A reference number for the invoice or related documents." ;
    rdfs:subClassOf :CompositeDataElement .

:BusinessProcess a owl:Class ;
    rdfs:label "Business Process" ;
    rdfs:comment "A business process such as Purchase-to-Pay." .

:ValidationConstraint a owl:Class ;
    rdfs:label "Validation Constraint" ;
    rdfs:comment "A constraint for validation, e.g., SHACL shape." .

:GLNIdentifier a owl:Class ;
    rdfs:label "GLN Identifier" ;
    rdfs:comment "A Global Location Number identifier." ;
    rdfs:subClassOf :SimpleDataElement .

:EN16931Alignment a owl:Class ;
    rdfs:label "EN 16931 Alignment" ;
    rdfs:comment "Alignment to EN 16931-1 semantic model." .

:P2POAlignment a owl:Class ;
    rdfs:label "P2P-O Alignment" ;
    rdfs:comment "Alignment to Purchase-to-Pay Ontology (P2P-O)." .

:RoleAssignment a owl:Class ;
    rdfs:label "Role Assignment" ;
    rdfs:comment "A reified relationship linking an organization to a role in the invoice context." .

#################################################################
# Object Properties
#################################################################

:containsMessage a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an Interchange Envelope to one or more Messages." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    owl:inverseOf :isContainedBy .

:isContainedBy a owl:ObjectProperty ;
    rdfs:label "is contained by" ;
    rdfs:comment "Links a Message to its containing InterchangeEnvelope." ;
    rdfs:domain :Message ;
    rdfs:range :InterchangeEnvelope ;
    owl:inverseOf :containsMessage .

:hasSegment a owl:ObjectProperty ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a Message to its Segments." ;
    rdfs:domain :Message ;
    rdfs:range :Segment ;
    owl:inverseOf :isSegmentOf .

:isSegmentOf a owl:ObjectProperty ;
    rdfs:label "is segment of" ;
    rdfs:comment "Links a Segment to its containing Message." ;
    rdfs:domain :Segment ;
    rdfs:range :Message ;
    owl:inverseOf :hasSegment .

:hasHeader a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has header" ;
    rdfs:comment "Links an Invoice Message to its header section." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceHeader ;
    owl:inverseOf :isHeaderOf .

:isHeaderOf a owl:ObjectProperty ;
    rdfs:label "is header of" ;
    rdfs:comment "Links InvoiceHeader to its InvoiceMessage." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasHeader .

:hasDetail a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has detail" ;
    rdfs:comment "Links an Invoice Message to its detail section." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceDetail ;
    owl:inverseOf :isDetailOf .

:isDetailOf a owl:ObjectProperty ;
    rdfs:label "is detail of" ;
    rdfs:comment "Links InvoiceDetail to its InvoiceMessage." ;
    rdfs:domain :InvoiceDetail ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasDetail .

:hasSummary a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has summary" ;
    rdfs:comment "Links an Invoice Message to its summary section." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceSummary ;
    owl:inverseOf :isSummaryOf .

:isSummaryOf a owl:ObjectProperty ;
    rdfs:label "is summary of" ;
    rdfs:comment "Links InvoiceSummary to its InvoiceMessage." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasSummary .

:hasLineItem a owl:ObjectProperty ;
    rdfs:label "has line item" ;
    rdfs:comment "Links an Invoice Detail to its Line Items." ;
    rdfs:domain :InvoiceDetail ;
    rdfs:range :LineItem ;
    owl:inverseOf :isLineItemOf .

:isLineItemOf a owl:ObjectProperty ;
    rdfs:label "is line item of" ;
    rdfs:comment "Links LineItem to its InvoiceDetail." ;
    rdfs:domain :LineItem ;
    rdfs:range :InvoiceDetail ;
    owl:inverseOf :hasLineItem .

:describesItem a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "describes item" ;
    rdfs:comment "Links a Line Item to the Item it describes." ;
    rdfs:domain :LineItem ;
    rdfs:range :Item ;
    owl:inverseOf :isDescribedBy .

:isDescribedBy a owl:ObjectProperty ;
    rdfs:label "is described by" ;
    rdfs:comment "Links Item to its describing LineItem." ;
    rdfs:domain :Item ;
    rdfs:range :LineItem ;
    owl:inverseOf :describesItem .

:hasNetPrice a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has net price" ;
    rdfs:comment "Links a Line Item to its net Price." ;
    rdfs:domain :LineItem ;
    rdfs:range :Price ;
    owl:inverseOf :isNetPriceOf .

:isNetPriceOf a owl:ObjectProperty ;
    rdfs:label "is net price of" ;
    rdfs:comment "Links Price to its LineItem." ;
    rdfs:domain :Price ;
    rdfs:range :LineItem ;
    owl:inverseOf :hasNetPrice .

:hasQuantity a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has quantity" ;
    rdfs:comment "The quantity of an item in a line item." ;
    rdfs:domain :LineItem ;
    rdfs:range xsd:decimal .

:hasTax a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has tax" ;
    rdfs:comment "Links an Invoice Summary to a Tax instance." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :Tax ;
    owl:inverseOf :isTaxOf .

:isTaxOf a owl:ObjectProperty ;
    rdfs:label "is tax of" ;
    rdfs:comment "Links Tax to its InvoiceSummary." ;
    rdfs:domain :Tax ;
    rdfs:range :InvoiceSummary ;
    owl:inverseOf :hasTax .

:hasInvoiceAmount a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "The total invoice amount in the summary." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range xsd:decimal .

:hasInvoiceNumber a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has invoice number" ;
    rdfs:comment "The invoice number in the header." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range xsd:string .

:hasReferenceNumber a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has reference number" ;
    rdfs:comment "Links an Invoice Header to a Reference Number." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :ReferenceNumber ;
    owl:inverseOf :isReferenceNumberOf .

:isReferenceNumberOf a owl:ObjectProperty ;
    rdfs:label "is reference number of" ;
    rdfs:comment "Links ReferenceNumber to its InvoiceHeader." ;
    rdfs:domain :ReferenceNumber ;
    rdfs:range :InvoiceHeader ;
    owl:inverseOf :hasReferenceNumber .

:hasDate a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has date" ;
    rdfs:comment "A generic date property (use DTMSegment for qualified dates)." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range xsd:string .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:label "involves organization" ;
    rdfs:comment "Links an Invoice Message to an involved Organization." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization ;
    owl:inverseOf :isInvolvedIn .

:isInvolvedIn a owl:ObjectProperty ;
    rdfs:label "is involved in" ;
    rdfs:comment "Links Organization to the InvoiceMessage it is involved in." ;
    rdfs:domain :Organization ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :involvesOrganization .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Links an Invoice Message to a RoleAssignment instance." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :RoleAssignment ;
    owl:inverseOf :isRoleAssignmentOf .

:isRoleAssignmentOf a owl:ObjectProperty ;
    rdfs:label "is role assignment of" ;
    rdfs:comment "Links RoleAssignment to its InvoiceMessage." ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasRoleAssignment .

:hasAgentRole a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has agent role" ;
    rdfs:comment "Links a RoleAssignment to an AgentRole." ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :AgentRole ;
    owl:inverseOf :isAgentRoleOf .

:isAgentRoleOf a owl:ObjectProperty ;
    rdfs:label "is agent role of" ;
    rdfs:comment "Links AgentRole to its RoleAssignment." ;
    rdfs:domain :AgentRole ;
    rdfs:range :RoleAssignment ;
    owl:inverseOf :hasAgentRole .

:hasParticipant a owl:ObjectProperty , owl:FunctionalProperty ;
    rdfs:label "has participant" ;
    rdfs:comment "Links a RoleAssignment to the Organization in that role." ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :Organization ;
    owl:inverseOf :isParticipantOf .

:isParticipantOf a owl:ObjectProperty ;
    rdfs:label "is participant of" ;
    rdfs:comment "Links Organization to its RoleAssignment." ;
    rdfs:domain :Organization ;
    rdfs:range :RoleAssignment ;
    owl:inverseOf :hasParticipant .

:hasAddress a owl:ObjectProperty ;
    rdfs:label "has address" ;
    rdfs:comment "Links an Organization to its Address." ;
    rdfs:domain :Organization ;
    rdfs:range :Address ;
    owl:inverseOf :isAddressOf .

:isAddressOf a owl:ObjectProperty ;
    rdfs:label "is address of" ;
    rdfs:comment "Links Address to its Organization." ;
    rdfs:domain :Address ;
    rdfs:range :Organization ;
    owl:inverseOf :hasAddress .

:hasGLN a owl:DatatypeProperty , owl:FunctionalProperty ;
    rdfs:label "has GLN" ;
    rdfs:comment "The Global Location Number of an Organization." ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string .

:alignedWithEN16931 a owl:ObjectProperty ;
    rdfs:label "aligned with EN 16931" ;
    rdfs:comment "Links an Invoice Message to EN16931Alignment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :EN16931Alignment ;
    owl:inverseOf :isEN16931AlignmentOf .

:isEN16931AlignmentOf a owl:ObjectProperty ;
    rdfs:label "is EN 16931 alignment of" ;
    rdfs:comment "Links EN16931Alignment to its InvoiceMessage." ;
    rdfs:domain :EN16931Alignment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :alignedWithEN16931 .

:alignedWithP2PO a owl:ObjectProperty ;
    rdfs:label "aligned with P2P-O" ;
    rdfs:comment "Links an Invoice Message to P2POAlignment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :P2POAlignment ;
    owl:inverseOf :isP2POAlignmentOf .

:isP2POAlignmentOf a owl:ObjectProperty ;
    rdfs:label "is P2P-O alignment of" ;
    rdfs:comment "Links P2POAlignment to its InvoiceMessage." ;
    rdfs:domain :P2POAlignment ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :alignedWithP2PO .

:validatesWith a owl:ObjectProperty ;
    rdfs:label "validates with" ;
    rdfs:comment "Links an Invoice Message to a ValidationConstraint (e.g. SHACL)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ValidationConstraint ;
    owl:inverseOf :isValidationConstraintOf .

:isValidationConstraintOf a owl:ObjectProperty ;
    rdfs:label "is validation constraint of" ;
    rdfs:comment "Links ValidationConstraint to its InvoiceMessage." ;
    rdfs:domain :ValidationConstraint ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :validatesWith .

:hasBusinessProcess a owl:ObjectProperty ;
    rdfs:label "has business process" ;
    rdfs:comment "Links an Invoice Message to a Business Process." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess ;
    owl:inverseOf :isBusinessProcessOf .

:isBusinessProcessOf a owl:ObjectProperty ;
    rdfs:label "is business process of" ;
    rdfs:comment "Links BusinessProcess to its InvoiceMessage." ;
    rdfs:domain :BusinessProcess ;
    rdfs:range :InvoiceMessage ;
    owl:inverseOf :hasBusinessProcess .

# Segment-specific object properties
:hasDTM a owl:ObjectProperty ;
    rdfs:label "has DTM segment" ;
    rdfs:comment "Links header or detail to a DTMSegment (qualified date/time)." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :DTMSegment ;
    owl:inverseOf :isDTMSegmentOf .

:isDTMSegmentOf a owl:ObjectProperty ;
    rdfs:label "is DTM segment of" ;
    rdfs:comment "Links DTMSegment to its InvoiceHeader." ;
    rdfs:domain :DTMSegment ;
    rdfs:range :InvoiceHeader ;
    owl:inverseOf :hasDTM .

:hasMOA a owl:ObjectProperty ;
    rdfs:label "has MOA segment" ;
    rdfs:comment "Links summary or line item to a MOASegment (qualified amount)." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :MOASegment ;
    owl:inverseOf :isMOASegmentOf .

:isMOASegmentOf a owl:ObjectProperty ;
    rdfs:label "is MOA segment of" ;
    rdfs:comment "Links MOASegment to its InvoiceSummary." ;
    rdfs:domain :MOASegment ;
    rdfs:range :InvoiceSummary ;
    owl:inverseOf :hasMOA .

:hasRFF a owl:ObjectProperty ;
    rdfs:label "has RFF segment" ;
    rdfs:comment "Links header or detail to a RFFSegment (reference)." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :RFFSegment ;
    owl:inverseOf :isRFFSegmentOf .

:isRFFSegmentOf a owl:ObjectProperty ;
