    rdfs:label "Role Assignment" ;
    rdfs:comment "A reified relationship linking an organization to a role in the invoice context." .

#################################################################
# Object Properties
#################################################################

:containsMessage a owl:ObjectProperty ;
    rdfs:label "contains message" ;
    rdfs:comment "Links an Interchange Envelope to one or more Messages." ;
    rdfs:domain :InterchangeEnvelope ;
    rdfs:range :Message ;
    owl:FunctionalProperty .

:hasSegment a owl:ObjectProperty ;
    rdfs:label "has segment" ;
    rdfs:comment "Links a Message to its Segments." ;
    rdfs:domain :Message ;
    rdfs:range :Segment .

:hasHeader a owl:ObjectProperty ;
    rdfs:label "has header" ;
    rdfs:comment "Links an Invoice Message to its header section." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceHeader ;
    owl:FunctionalProperty .

:hasDetail a owl:ObjectProperty ;
    rdfs:label "has detail" ;
    rdfs:comment "Links an Invoice Message to its detail section." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceDetail ;
    owl:FunctionalProperty .

:hasSummary a owl:ObjectProperty ;
    rdfs:label "has summary" ;
    rdfs:comment "Links an Invoice Message to its summary section." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :InvoiceSummary ;
    owl:FunctionalProperty .

:hasLineItem a owl:ObjectProperty ;
    rdfs:label "has line item" ;
    rdfs:comment "Links an Invoice Detail to its Line Items." ;
    rdfs:domain :InvoiceDetail ;
    rdfs:range :LineItem .

:describesItem a owl:ObjectProperty ;
    rdfs:label "describes item" ;
    rdfs:comment "Links a Line Item to the Item it describes." ;
    rdfs:domain :LineItem ;
    rdfs:range :Item ;
    owl:FunctionalProperty .

:hasNetPrice a owl:ObjectProperty ;
    rdfs:label "has net price" ;
    rdfs:comment "Links a Line Item to its net Price." ;
    rdfs:domain :LineItem ;
    rdfs:range :Price ;
    owl:FunctionalProperty .

:hasQuantity a owl:DatatypeProperty ;
    rdfs:label "has quantity" ;
    rdfs:comment "The quantity of an item in a line item." ;
    rdfs:domain :LineItem ;
    rdfs:range xsd:decimal ;
    owl:FunctionalProperty .

:hasTax a owl:ObjectProperty ;
    rdfs:label "has tax" ;
    rdfs:comment "Links an Invoice Summary to a Tax instance." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :Tax ;
    owl:FunctionalProperty .

:hasInvoiceAmount a owl:DatatypeProperty ;
    rdfs:label "has invoice amount" ;
    rdfs:comment "The total invoice amount in the summary." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range xsd:decimal ;
    owl:FunctionalProperty .

:hasInvoiceNumber a owl:DatatypeProperty ;
    rdfs:label "has invoice number" ;
    rdfs:comment "The invoice number in the header." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range xsd:string ;
    owl:FunctionalProperty .

:hasReferenceNumber a owl:ObjectProperty ;
    rdfs:label "has reference number" ;
    rdfs:comment "Links an Invoice Header to a Reference Number." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :ReferenceNumber ;
    owl:FunctionalProperty .

:hasDate a owl:DatatypeProperty ;
    rdfs:label "has date" ;
    rdfs:comment "A generic date property (use DTM_Segment for qualified dates)." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range xsd:string ;
    owl:FunctionalProperty .

:involvesOrganization a owl:ObjectProperty ;
    rdfs:label "involves organization" ;
    rdfs:comment "Links an Invoice Message to an involved Organization." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :Organization .

:hasRoleAssignment a owl:ObjectProperty ;
    rdfs:label "has role assignment" ;
    rdfs:comment "Links an Invoice Message to a RoleAssignment instance." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :RoleAssignment .

:hasAgentRole a owl:ObjectProperty ;
    rdfs:label "has agent role" ;
    rdfs:comment "Links a RoleAssignment to an AgentRole." ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :AgentRole ;
    owl:FunctionalProperty .

:hasParticipant a owl:ObjectProperty ;
    rdfs:label "has participant" ;
    rdfs:comment "Links a RoleAssignment to the Organization in that role." ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :Organization ;
    owl:FunctionalProperty .

:hasAddress a owl:ObjectProperty ;
    rdfs:label "has address" ;
    rdfs:comment "Links an Organization to its Address." ;
    rdfs:domain :Organization ;
    rdfs:range :Address .

:hasGLN a owl:DatatypeProperty ;
    rdfs:label "has GLN" ;
    rdfs:comment "The Global Location Number of an Organization." ;
    rdfs:domain :Organization ;
    rdfs:range xsd:string ;
    owl:FunctionalProperty .

:alignedWithEN16931 a owl:ObjectProperty ;
    rdfs:label "aligned with EN 16931" ;
    rdfs:comment "Links an Invoice Message to EN 16931 Alignment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :EN16931_Alignment .

:alignedWithP2PO a owl:ObjectProperty ;
    rdfs:label "aligned with P2P-O" ;
    rdfs:comment "Links an Invoice Message to P2P-O Alignment." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :P2PO_Alignment .

:validatesWith a owl:ObjectProperty ;
    rdfs:label "validates with" ;
    rdfs:comment "Links an Invoice Message to a ValidationConstraint (e.g. SHACL)." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :ValidationConstraint .

:hasBusinessProcess a owl:ObjectProperty ;
    rdfs:label "has business process" ;
    rdfs:comment "Links an Invoice Message to a Business Process." ;
    rdfs:domain :InvoiceMessage ;
    rdfs:range :BusinessProcess .

# Segment-specific object properties
:hasDTM a owl:ObjectProperty ;
    rdfs:label "has DTM segment" ;
    rdfs:comment "Links header or detail to a DTM_Segment (qualified date/time)." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :DTM_Segment .

:hasMOA a owl:ObjectProperty ;
    rdfs:label "has MOA segment" ;
    rdfs:comment "Links summary or line item to a MOA_Segment (qualified amount)." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :MOA_Segment .

:hasRFF a owl:ObjectProperty ;
    rdfs:label "has RFF segment" ;
    rdfs:comment "Links header or detail to a RFF_Segment (reference)." ;
    rdfs:domain :InvoiceHeader ;
    rdfs:range :RFF_Segment .

:hasLOC a owl:ObjectProperty ;
    rdfs:label "has LOC segment" ;
    rdfs:comment "Links detail or line item to a LOC_Segment (location)." ;
    rdfs:domain :InvoiceDetail ;
    rdfs:range :LOC_Segment .

:hasLIN a owl:ObjectProperty ;
    rdfs:label "has LIN segment" ;
    rdfs:comment "Links detail to a LIN_Segment (line item)." ;
    rdfs:domain :InvoiceDetail ;
    rdfs:range :LIN_Segment .

:hasPRI a owl:ObjectProperty ;
    rdfs:label "has PRI segment" ;
    rdfs:comment "Links line item to a PRI_Segment (price)." ;
    rdfs:domain :LineItem ;
    rdfs:range :PRI_Segment .

:hasQTY a owl:ObjectProperty ;
    rdfs:label "has QTY segment" ;
    rdfs:comment "Links line item to a QTY_Segment (quantity)." ;
    rdfs:domain :LineItem ;
    rdfs:range :QTY_Segment .

:hasTAX a owl:ObjectProperty ;
    rdfs:label "has TAX segment" ;
    rdfs:comment "Links summary or line item to a TAX_Segment (tax info)." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :TAX_Segment .

:hasCUX a owl:ObjectProperty ;
    rdfs:label "has CUX segment" ;
    rdfs:comment "Links summary or line item to a CUX_Segment (currency info)." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :CUX_Segment .

:hasUNS a owl:ObjectProperty ;
    rdfs:label "has UNS segment" ;
    rdfs:comment "Links summary to a UNS_Segment (section control)." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :UNS_Segment .

#################################################################
# Data Properties (Qualifiers & Values)
#################################################################

:dtmQualifier a owl:DatatypeProperty ;
    rdfs:label "DTM qualifier" ;
    rdfs:comment "Qualifier code for DTM segment (e.g., 137=Document date)." ;
    rdfs:domain :DTM_Segment ;
    rdfs:range xsd:string ;
    owl:FunctionalProperty .

:dtmValue a owl:DatatypeProperty ;
    rdfs:label "DTM value" ;
    rdfs:comment "Date/time value for DTM segment." ;
    rdfs:domain :DTM_Segment ;
    rdfs:range xsd:string ;
    owl:FunctionalProperty .

:moaQualifier a owl:DatatypeProperty ;
    rdfs:label "MOA qualifier" ;
    rdfs:comment "Qualifier code for MOA segment (e.g., 9=Invoice amount)." ;
    rdfs:domain :MOA_Segment ;
    rdfs:range xsd:string ;
    owl:FunctionalProperty .

:moaValue a owl:DatatypeProperty ;
    rdfs:label "MOA value" ;
    rdfs:comment "Monetary value for MOA segment." ;
    rdfs:domain :MOA_Segment ;
    rdfs:range xsd:decimal ;
    owl:FunctionalProperty .

#################################################################
# Disjointness Axioms
#################################################################

[] a owl:AllDisjointClasses ;
    owl:members ( :InvoiceHeader :InvoiceDetail :InvoiceSummary ) .

[] a owl:AllDisjointClasses ;
    owl:members ( :Organization :AgentRole :Address :LineItem :Item :Price :Tax :ReferenceNumber :BusinessProcess ) .

#################################################################
# Pivot Class Reification
#################################################################

:RoleAssignment a owl:Class ;
    rdfs:label "Role Assignment" ;
    rdfs:comment "A reified n-ary relationship linking an Organization to an AgentRole in the context of an Invoice Message." .

:hasAgentRole a owl:ObjectProperty ;
    rdfs:label "has agent role" ;
    rdfs:comment "Links RoleAssignment to AgentRole." ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :AgentRole ;
    owl:FunctionalProperty .

:hasParticipant a owl:ObjectProperty ;
    rdfs:label "has participant" ;
    rdfs:comment "Links RoleAssignment to Organization." ;
    rdfs:domain :RoleAssignment ;
    rdfs:range :Organization ;
    owl:FunctionalProperty .

#################################################################
# Class Equivalence and Restrictions
#################################################################

:BuyerRole a owl:Class ;
    rdfs:label "Buyer Role" ;
    rdfs:comment "A role indicating buying party in the invoice." ;
    owl:equivalentClass [ a owl:Restriction ; owl:onProperty :hasAgentRole ; owl:hasValue :Buyer ] .

:InvoiceWithEN16931Alignment a owl:Class ;
    rdfs:label "Invoice with EN 16931 Alignment" ;
    rdfs:comment "An Invoice Message aligned with EN 16931." ;
    owl:equivalentClass [ a owl:Restriction ; owl:onProperty :alignedWithEN16931 ; owl:someValuesFrom :EN16931_Alignment ] .

