    rdfs:domain :InvoiceHeader ;
    rdfs:range :RFFSegment ;
    owl:inverseOf :isRFFSegmentOf .

:isRFFSegmentOf a owl:ObjectProperty ;
    rdfs:label "is RFF segment of" ;
    rdfs:comment "Links RFFSegment to its InvoiceHeader." ;
    rdfs:domain :RFFSegment ;
    rdfs:range :InvoiceHeader ;
    owl:inverseOf :hasRFF .

:hasLOC a owl:ObjectProperty ;
    rdfs:label "has LOC segment" ;
    rdfs:comment "Links detail or line item to a LOCSegment (location)." ;
    rdfs:domain :InvoiceDetail ;
    rdfs:range :LOCSegment ;
    owl:inverseOf :isLOCSegmentOf .

:isLOCSegmentOf a owl:ObjectProperty ;
    rdfs:label "is LOC segment of" ;
    rdfs:comment "Links LOCSegment to its InvoiceDetail." ;
    rdfs:domain :LOCSegment ;
    rdfs:range :InvoiceDetail ;
    owl:inverseOf :hasLOC .

:hasLIN a owl:ObjectProperty ;
    rdfs:label "has LIN segment" ;
    rdfs:comment "Links detail to a LINSegment (line item)." ;
    rdfs:domain :InvoiceDetail ;
    rdfs:range :LINSegment ;
    owl:inverseOf :isLINSegmentOf .

:isLINSegmentOf a owl:ObjectProperty ;
    rdfs:label "is LIN segment of" ;
    rdfs:comment "Links LINSegment to its InvoiceDetail." ;
    rdfs:domain :LINSegment ;
    rdfs:range :InvoiceDetail ;
