:hasPRI a owl:ObjectProperty ;
    rdfs:label "has PRI segment" ;
    rdfs:comment "Links line item to a PRISegment (price)." ;
    rdfs:domain :LineItem ;
    rdfs:range :PRISegment ;
    owl:inverseOf :isPRISegmentOf .

:isPRISegmentOf a owl:ObjectProperty ;
    rdfs:label "is PRI segment of" ;
    rdfs:comment "Links PRISegment to its LineItem." ;
    rdfs:domain :PRISegment ;
    rdfs:range :LineItem ;
