:hasCUX a owl:ObjectProperty ;
    rdfs:label "has CUX segment" ;
    rdfs:comment "Links summary or line item to a CUXSegment (currency info)." ;
    rdfs:domain :InvoiceSummary ;
    rdfs:range :CUXSegment ;
